INSERT INTO tb_worklog (worklog_id, author_id, team_id, title, request_content, work_content, status_code, importance_code, actual_hours, instruction_date, due_date, completion_date, ai_summary, ai_summary_edited, ai_processing_status, is_deleted, created_at, updated_at) VALUES
  (1001, 5, 111, '부품 결품 위험 조기 탐지 고객사 문의 접수', '현대자동차 부품 수급 데이터 정합성 컨설팅 TF에서 부품 결품 위험 조기 탐지 관련 확인 요청이 들어와 김도윤 담당자가 접수 단계 기록을 남겼다. 이전 유사 업무로는 108 운영 데이터 품질 진단의 기준정보 점검 방식을 참고하되, 이번 고객사 조건을 별도로 구분해 달라는 요청이었다.', '김도윤 담당자는 공급망 데이터 정합성 리드 관점에서 초기 문의를 받자마자 고객사 원천 화면과 내부 기록을 분리해 보았다. 부품 결품 위험 조기 탐지 접수 단계에서는 108 운영 데이터 품질 진단의 기준정보 점검 방식을 바로 복사하지 않고, 고객사 문의 표현과 내부 기준 용어를 함께 남겼다. 접수 메모에는 고객사 원문, 내부 변환 용어, 첫 확인자를 구분해 김도윤 담당자의 출발점이 보이게 했다. 마지막에는 부품 결품 위험 조기 탐지의 재현 조건을 짧게 묶어 팀장이 바로 우선순위를 판단할 수 있게 했다.', 'PENDING', 'HIGH', 1.0, '2026-04-06', '2026-04-09', NULL, NULL, false, 'COMPLETED', false, '2026-04-06 09:00:00', '2026-04-06 09:00:00'),
  (1002, 7, 111, '부품 결품 위험 조기 탐지 원인 후보 분리', '현대자동차 부품 수급 데이터 정합성 컨설팅 TF에서 부품 결품 위험 조기 탐지 관련 확인 요청이 들어와 정유진 담당자가 원인분석 단계 기록을 남겼다. 이전 유사 업무로는 108 운영 데이터 품질 진단의 기준정보 점검 방식을 참고하되, 이번 고객사 조건을 별도로 구분해 달라는 요청이었다.', '정유진 담당자는 수량 차이 예외 분석 관점에서 전일 기록과 로그 시간을 맞춰 보며 원인 후보를 두 갈래로 나누었다. 정유진 담당자는 108 운영 데이터 품질 진단의 기준정보 점검 방식에서 쓰던 비교 순서를 참고하되, 이번에는 수량 차이 예외 분석 관점의 원인 후보만 따로 좁혔다. 원인분석 기록은 확정 로그와 추정 메모를 섞지 않고, 부품 결품 위험 조기 탐지 판단이 흔들린 지점을 별도로 표시했다. 다음 단계에서는 정유진 담당자가 남긴 원인 후보 중 고객사 확인이 필요한 항목부터 이어 보면 된다.', 'IN_PROGRESS', 'NORMAL', 2.5, '2026-04-08', '2026-04-12', NULL, NULL, false, 'COMPLETED', false, '2026-04-08 09:13:00', '2026-04-08 09:13:00'),
  (1003, 10, 111, '부품 결품 위험 조기 탐지 기준 보정 작업', '현대자동차 부품 수급 데이터 정합성 컨설팅 TF에서 부품 결품 위험 조기 탐지 관련 확인 요청이 들어와 윤가은 담당자가 보정작업 단계 기록을 남겼다. 이전 유사 업무로는 108 운영 데이터 품질 진단의 기준정보 점검 방식을 참고하되, 이번 고객사 조건을 별도로 구분해 달라는 요청이었다.', '윤가은 담당자는 부품/협력사 기준정보 정리 관점에서 바로 고칠 수 있는 기준과 고객사 확인이 필요한 기준을 나눠 처리했다. 부품 결품 위험 조기 탐지 보정 메모에는 108 운영 데이터 품질 진단의 기준정보 점검 방식과 닮은 기준을 표시하되, 실제 수정 대상과 보류 대상을 분리했다. 보정 내용은 부품/협력사 기준정보 정리 기준에서 즉시 반영한 항목, 고객사 답변 대기 항목, 다음 검증 항목으로 나누었다. 수정 범위가 넓어지지 않도록 부품 결품 위험 조기 탐지의 다음 검증 항목과 담당 부서를 같이 적었다.', 'IN_PROGRESS', 'HIGH', 3.5, '2026-04-10', '2026-04-15', NULL, NULL, false, 'COMPLETED', false, '2026-04-10 09:26:00', '2026-04-10 09:26:00'),
  (1004, 16, 111, '부품 결품 위험 조기 탐지 재검증 결과 정리', '현대자동차 부품 수급 데이터 정합성 컨설팅 TF에서 부품 결품 위험 조기 탐지 관련 확인 요청이 들어와 강민호 담당자가 검증 단계 기록을 남겼다. 이전 유사 업무로는 108 운영 데이터 품질 진단의 기준정보 점검 방식을 참고하되, 이번 고객사 조건을 별도로 구분해 달라는 요청이었다.', '강민호 담당자는 창고 입출고 운영 분석 관점에서 수정 뒤 같은 조건을 다시 만들어 결과가 달라졌는지 비교했다. 검증 단계에서는 108 운영 데이터 품질 진단의 기준정보 점검 방식과 이어지는 검색 단서를 남기면서도, 이번 고객사에서 달라진 조건을 먼저 적었다. 검증 결과는 완료 여부보다 부품 결품 위험 조기 탐지가 다시 검색될 때 비교해야 할 조건과 이전 업무와 달라진 지점을 함께 남겼다. 완료 처리하면서도 부품 결품 위험 조기 탐지가 재발하면 어떤 검색어와 어떤 비교 기준으로 다시 볼지 남겼다.', 'COMPLETED', 'NORMAL', 2.0, '2026-04-12', '2026-04-18', '2026-04-19', NULL, false, 'COMPLETED', false, '2026-04-12 09:39:00', '2026-04-19 17:27:00'),
  (1005, 7, 111, '협력사 납기 차이 재집계 고객사 문의 접수', '현대자동차 부품 수급 데이터 정합성 컨설팅 TF에서 협력사 납기 차이 재집계 관련 확인 요청이 들어와 정유진 담당자가 접수 단계 기록을 남겼다. 이전 유사 업무로는 107 정산 예외 분석의 수량 차이 추적 방식을 참고하되, 이번 고객사 조건을 별도로 구분해 달라는 요청이었다.', '정유진 담당자는 수량 차이 예외 분석 관점에서 초기 문의를 받자마자 고객사 원천 화면과 내부 기록을 분리해 보았다. 협력사 납기 차이 재집계 접수 단계에서는 107 정산 예외 분석의 수량 차이 추적 방식을 바로 복사하지 않고, 고객사 문의 표현과 내부 기준 용어를 함께 남겼다. 접수 메모에는 고객사 원문, 내부 변환 용어, 첫 확인자를 구분해 정유진 담당자의 출발점이 보이게 했다. 마지막에는 협력사 납기 차이 재집계의 재현 조건을 짧게 묶어 팀장이 바로 우선순위를 판단할 수 있게 했다.', 'PENDING', 'HIGH', 1.0, '2026-04-14', '2026-04-18', NULL, NULL, false, 'COMPLETED', false, '2026-04-14 10:00:00', '2026-04-14 10:00:00'),
